# Generated by complete-me VERSION from: help.
_complete_me_claude() {
    local cur="${COMP_WORDS[COMP_CWORD]}" prev="${COMP_WORDS[COMP_CWORD-1]}"
    local path="" i w words files
    local -a tree=('agents' 'attach' 'auth' 'auto-mode' 'doctor' 'gateway' 'import' 'install' 'logs' 'mcp' 'purge' 'respawn' 'rm' 'setup-token' 'ultrareview')
    for ((i = 1; i < COMP_CWORD; i++)); do
        w="${COMP_WORDS[i]}"
        [[ $w == -* ]] && continue
        local cand="${path:+$path }$w" t found=0
        for t in "${tree[@]}"; do [[ $t == "$cand" ]] && found=1 && break; done
        ((found)) && path="$cand" || break
    done
    case "$path|$prev" in
        '|--autocompact') COMPREPLY=($(compgen -W 'auto tokens' -- "$cur")); return;;
        '|--cloud') COMPREPLY=($(compgen -W 'description session_id url' -- "$cur")); return;;
        '|--input-format') COMPREPLY=($(compgen -W 'text stream-json' -- "$cur")); return;;
        '|--output-format') COMPREPLY=($(compgen -W 'text json stream-json' -- "$cur")); return;;
        '|--permission-mode') COMPREPLY=($(compgen -W 'acceptEdits auto bypassPermissions manual dontAsk plan' -- "$cur")); return;;
        '|--permission-prompts') COMPREPLY=($(compgen -W 'host none' -- "$cur")); return;;
        '|--prompt-suggestions') COMPREPLY=($(compgen -W 'true false 1 0 yes no on off' -- "$cur")); return;;
        '|--system-prompt-snapshot') COMPREPLY=($(compgen -W 'on off' -- "$cur")); return;;
    esac
    case "$path" in
        '') words='agents attach auth auto-mode doctor gateway import install logs mcp purge respawn rm setup-token ultrareview --add-dir --agent --agents --allow-dangerously-skip-permissions --allowedTools --allowed-tools --append-system-prompt --autocompact --ax-screen-reader --bg --background --bare --betas --brief --chrome --cloud -c --continue --dangerously-skip-permissions -d --debug --debug-file --desktop --disable-slash-commands --disallowedTools --disallowed-tools --effort --environment --exclude-dynamic-system-prompt-sections --fallback-model --file --fork-session --forward-subagent-text --from-pr -h --help --ide --include-hook-events --include-partial-messages --input-format --json-schema --max-budget-usd --mcp-config --model -n --name --no-chrome --no-session-persistence --output-format --permission-mode --permission-prompts --plugin-dir --plugin-url -p --print --prompt-suggestions --remote-control --remote-control-session-name-prefix --replay-user-messages --restricted -r --resume --safe-mode --session-id --setting-sources --settings --strict-mcp-config --system-prompt --system-prompt-snapshot --teleport --tmux --tools --verbose -v --version -w --worktree'; files=0;;
        'agents') words=''; files=0;;
        'attach') words=''; files=0;;
        'auth') words=''; files=1;;
        'auto-mode') words=''; files=1;;
        'doctor') words=''; files=1;;
        'gateway') words=''; files=0;;
        'import') words=''; files=1;;
        'install') words=''; files=1;;
        'logs') words=''; files=0;;
        'mcp') words=''; files=1;;
        'purge') words=''; files=1;;
        'respawn') words=''; files=0;;
        'rm') words=''; files=0;;
        'setup-token') words=''; files=1;;
        'ultrareview') words=''; files=1;;
        *) words=""; files=1;;
    esac
    COMPREPLY=($(compgen -W "$words" -- "$cur"))
    if ((files)) && [[ $cur != -* ]]; then
        COMPREPLY+=($(compgen -f -- "$cur"))
    fi
}
complete -o bashdefault -o default -F _complete_me_claude claude
